int32_t TIDL_tfOutReshapeConvLayer(sTIDL_OrgNetwork_t   *pOrgTIDLNetStructure, int32_t layerIndex)
{
  int32_t status = 0;
  sTIDL_LayerPC_t &TIDLPCLayers = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex];
  sTIDL_ConvParams_t &convParams = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex].layerParams.convParams;
  sTIDL_DataParams_t *inDataParams[1] = { &TIDLPCLayers.inData[0] };
  TIDL_ShapeContext_t ctx;
  ctx.isCompileTime = 1;
  ctx.pcLayer       = (void *)&TIDLPCLayers;
  ctx.configParams  = (void *)&gParams;

  TIDLPCLayers.outData[0].elementType = tidl_getElementType(1);
  if((gParams.modelType == 3) || (gParams.modelType == 5))
  {
    if(TIDLPCLayers.inData[0].dimValues[TIDL_DIM_NUMCH] != convParams.numInChannels)
    {
      convParams.numGroups = TIDLPCLayers.inData[0].dimValues[TIDL_DIM_NUMCH]/convParams.numInChannels;
      if((convParams.numGroups *convParams.numInChannels) != TIDLPCLayers.inData[0].dimValues[TIDL_DIM_NUMCH])
      {
        TIDL_GLOBAL_REPORT_ERROR("convParams.numInChannels is not multiple of convParams.numGroups");
        return TIDL_IMPORT_DIAGNOSIS_RETURN_FAIL;
      }
      convParams.numInChannels = TIDLPCLayers.inData[0].dimValues[TIDL_DIM_NUMCH];
    }
  }

  if((TIDLPCLayers.actParams.actType == TIDL_RelU6) || (TIDLPCLayers.actParams.actType == TIDL_RelU) ||
    ((TIDLPCLayers.clipParams.isClipEnabled == 1) && (TIDLPCLayers.clipParams.clipMin >= 0)))
  {
    TIDLPCLayers.outData[0].elementType = tidl_getElementType(0);
  }
  /* Conversting 2x2 kernelw ith stride 2x2 to 3x3 kernel */
  if((convParams.kernelH == 2) &&
    (convParams.kernelW == 2) &&
    (convParams.strideW == 2) &&
    (convParams.strideH == 2) &&
    (convParams.dilationW == 1) &&
    (convParams.dilationH == 1))
  {
    convParams.kernelW = 3;
    convParams.kernelH = 3;

   // To prevent the condition when padH or padW will become greater than 1
    if (convParams.padT <= convParams.padB && convParams.padL <= convParams.padR )
    {
      convParams.padT += 1;
      convParams.padL += 1;
      status = TIDL_zeroPadKernelToIncreaseSize(TIDLPCLayers.weights, 2,2,3,3,1);
    }
    else{
      convParams.padB += 1;
      convParams.padR += 1;
      status =TIDL_zeroPadKernelToIncreaseSize(TIDLPCLayers.weights, 2,2,3,3,0);
    }
    
    convParams.padH = max(convParams.padT, convParams.padB);
    convParams.padW = max(convParams.padL, convParams.padR);

    TIDLPCLayers.layerPCParams.convParams.tensorWidth = convParams.kernelW;
    TIDLPCLayers.layerPCParams.convParams.tensorHeight = convParams.kernelH;

    if((gParams.modelType == TIDL_IMPORT_MODEL_FORMAT_TFLITE) || (gParams.modelType == TIDL_IMPORT_MODEL_FORMAT_TENSORFLOW)
     ||(gParams.modelType == TIDL_IMPORT_MODEL_FORMAT_TFLITE_RT))
    {
      TIDLPCLayers.strideOffsetMethod = TIDL_StrideOffsetTopLeft;
    }
  }

  TIDL_shapeInfer_Conv(&TIDLPCLayers.layerParams, inDataParams, 1, &TIDLPCLayers.outData[0], &ctx);

  /* Update numInChannels from the actual input tensor (compile-time only).
   * At runtime the weights are fixed so numInChannels never changes. */
  convParams.numInChannels = TIDLPCLayers.inData[0].dimValues[TIDL_DIM_NUMCH];

  TIDLPCLayers.numMacs =
    (int64_t)(((int64_t)TIDLPCLayers.outData[0].dimValues[TIDL_DIM_BATCH] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM1] *TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM2] *TIDLPCLayers.outData[0].dimValues[TIDL_DIM_NUMCH] *
      TIDLPCLayers.outData[0].dimValues[TIDL_DIM_HEIGHT] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_WIDTH] *
      convParams.kernelW *convParams.kernelH *
      TIDLPCLayers.inData[0].dimValues[TIDL_DIM_NUMCH]) / convParams.numGroups);
  /*
  * Setting the pad parameter just in case it is not set or when we have strided case as pad does not correctly calculated for Strided Case
  */
   if(convParams.padL==-1 || convParams.padR==-1 || convParams.padT==-1 || convParams.padB==-1 || convParams.strideW > 1 || convParams.strideH > 1)
  {
    TIDL_IMPORT_CHECK_AND_RETURN(tidl_setLRTBpad(TIDLPCLayers), "");
  }

  /*Onnx Specific criteria:*/
  if((((convParams.kernelH % convParams.strideH) == 1)  || ((convParams.kernelW % convParams.strideW) == 1)) &&  (TIDLPCLayers.strideOffsetMethod == TIDL_StrideOffsetTopLeft) &&
  ((gParams.modelType == TIDL_IMPORT_MODEL_FORMAT_ONNX) || (gParams.modelType == TIDL_IMPORT_MODEL_FORMAT_ONNX_RT)))
  {
    TIDL_IMPORT_CHECK_AND_RETURN(tidl_setLRTBpad(TIDLPCLayers), "");
  }

  /*
   * Handle Random Coeff Case
   */
  int32_t dataSize;

  dataSize = convParams.kernelH * convParams.kernelW *
             convParams.numOutChannels *
             TIDLPCLayers.inData[0].dimValues[TIDL_DIM_NUMCH] / convParams.numGroups;

  if(TIDLPCLayers.weights.ptr == NULL ||
     TIDLPCLayers.weights.bufSize != dataSize)
  {
    TIDL_GLOBAL_REPORT_WARNING("Conv Layer %s's coeff cannot be found(or not match) in coeff file, "
           "Random coeff will be generated! "
           "Only for evaluation usage! "
           "Results are all random!", TIDLPCLayers.name);
    // TVM/Relay import wants to abort on this error ("warning")
    if (gParams.modelType == 4)  TIDL_GLOBAL_REPORT_FATAL_AND_ABORT("TVM/Relay import. Aborting");

    float*  data;
    data = (float *)my_malloc(dataSize*sizeof(float));

    for (int i = 0; i < dataSize; i++) {
      int32_t val = (rand() & (0X7FFFFFFF));
      data[i] = ((float)((rand() & 1) ? val : -val)) / (0X3FFFFF);
    }

    TIDLPCLayers.weights.ptr = data;
    TIDLPCLayers.weights.bufSize = dataSize;
  }

  /*
   * Handle Random Bias Case
   */
  dataSize = convParams.numOutChannels;

  if(convParams.enableBias &&
    (TIDLPCLayers.bias.ptr == NULL ||
     TIDLPCLayers.bias.bufSize != dataSize))
  {
    /* need a better message here or might want to report error */
    TIDL_GLOBAL_REPORT_WARNING("Conv Layer %s's bias cannot be found(or not match) in coeff file, "
           "Random bias will be generated "
           "only for evaluation usage. "
           "Results are all random", TIDLPCLayers.name);
    // TVM/Relay import wants to abort on this error ("warning")
    if (gParams.modelType == 4)  TIDL_GLOBAL_REPORT_FATAL_AND_ABORT("TVM/Relay import. Aborting");

    float*  data;
    data = (float *)my_malloc(dataSize*sizeof(float));

    for (int i = 0; i < dataSize; i++) {
      int32_t val = (rand() & (0X7FFFFFFF));
      data[i] = ((float)((rand() & 1) ? val : -val)) / (0XFFFFFF);
    }

    TIDLPCLayers.bias.ptr = data;
    TIDLPCLayers.bias.bufSize = dataSize;
  }

  return status;
}

int32_t TIDL_tfOutReshapeResize(sTIDL_OrgNetwork_t   *pOrgTIDLNetStructure, int32_t layerIndex)
{
  sTIDL_LayerPC_t &TIDLPCLayers = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex];
  sTIDL_DataParams_t *inDataParams[1] = { &TIDLPCLayers.inData[0] };
  TIDL_ShapeContext_t ctx;
  ctx.isCompileTime = 1;
  ctx.pcLayer       = (void *)&TIDLPCLayers;
  ctx.configParams  = (void *)&gParams;

  TIDLPCLayers.outData[0].elementType = TIDLPCLayers.inData[0].elementType;
  TIDLPCLayers.outData[0].numDim = TIDLPCLayers.inData[0].numDim;

  TIDL_shapeInfer_Resize(&TIDLPCLayers.layerParams, inDataParams, 1, &TIDLPCLayers.outData[0], &ctx);

  TIDLPCLayers.numMacs =
    (int64_t)((int64_t)TIDLPCLayers.outData[0].dimValues[TIDL_DIM_BATCH]* TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM1] *TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM2] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_NUMCH] *
      TIDLPCLayers.outData[0].dimValues[TIDL_DIM_HEIGHT] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_WIDTH] * 4);
  return 0;
}


int32_t TIDL_tfOutReshapePoolingLayer(sTIDL_OrgNetwork_t   *pOrgTIDLNetStructure, int32_t layerIndex)
{
  sTIDL_LayerPC_t &TIDLPCLayers = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex];
  sTIDL_PoolingParams_t &poolParams = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex].layerParams.poolParams;
  sTIDL_DataParams_t *inDataParams[1] = { &TIDLPCLayers.inData[0] };
  TIDL_ShapeContext_t ctx;
  ctx.isCompileTime = 1;
  ctx.pcLayer       = (void *)&TIDLPCLayers;
  ctx.configParams  = (void *)&gParams;
  
  TIDLPCLayers.outData[0].elementType = TIDLPCLayers.inData[0].elementType;
  TIDLPCLayers.outData[0].numDim = TIDLPCLayers.inData[0].numDim;

  int32_t isGlobalAvgPooling = (poolParams.kernelH  == TIDLPCLayers.inData[0].dimValues[TIDL_DIM_HEIGHT]) &&
                            (poolParams.kernelW  == TIDLPCLayers.inData[0].dimValues[TIDL_DIM_WIDTH]) &&
                            (poolParams.poolingType == TIDL_AveragePooling);

  if(isGlobalAvgPooling)
  {
    poolParams.kernelH = 0;
    poolParams.kernelW = 0;
    poolParams.padW    = 0;
    poolParams.padH    = 0;
    poolParams.padT    = 0;
    poolParams.padB    = 0;
    poolParams.padL    = 0;
    poolParams.padR    = 0;

  }

  if((gParams.modelType == TIDL_IMPORT_MODEL_FORMAT_TFLITE) || (gParams.modelType == TIDL_IMPORT_MODEL_FORMAT_TFLITE_RT))
  {
    if((poolParams.strideH == 2) && ((TIDLPCLayers.inData[0].dimValues[TIDL_DIM_HEIGHT] & 1)  == 0))
    {
      TIDLPCLayers.strideOffsetMethod = TIDL_StrideOffsetCenter; /*for tflite padding should be set according to TIDL_StrideOffsetCenter*/
    }
  }

  TIDL_shapeInfer_Pooling(&TIDLPCLayers.layerParams, inDataParams, 1,
                          &TIDLPCLayers.outData[0], &ctx);

  if (poolParams.kernelH > 0 || poolParams.kernelW > 0)
  {
    // Use the default padding from onnx importer for 32 bit compilation.
    if(!(isGlobalAvgPooling) && gParams.numParamBits !=32)
    {
      /* Using abort here, needs to change calling function structure for clean exit */
      TIDL_IMPORT_CHECK_AND_ABORT(tidl_setLRTBpad(TIDLPCLayers),"");
    }
    TIDLPCLayers.numMacs =
      (int64_t)((int64_t)TIDLPCLayers.outData[0].dimValues[TIDL_DIM_BATCH] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM1] *TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM2]* TIDLPCLayers.outData[0].dimValues[TIDL_DIM_NUMCH] *
        TIDLPCLayers.outData[0].dimValues[TIDL_DIM_HEIGHT] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_WIDTH] *
        poolParams.kernelW *poolParams.kernelH);
  }
  else
  {
    TIDLPCLayers.numMacs =
      (int64_t)((int64_t)TIDLPCLayers.outData[0].dimValues[TIDL_DIM_BATCH]* TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM1] *TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM2] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_NUMCH] *
        TIDLPCLayers.outData[0].dimValues[TIDL_DIM_HEIGHT] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_WIDTH]);
  }

  int32_t  outIdx = tidl_getOutLayer(pOrgTIDLNetStructure, pOrgTIDLNetStructure->numLayers, TIDLPCLayers.outData[0].dataId);
  if (outIdx == -1)
  {
    return TIDL_IMPORT_DIAGNOSIS_RETURN_FAIL;
  }
  sTIDL_LayerPC_t &TIDLPCLayerOut = pOrgTIDLNetStructure->TIDLPCLayers[outIdx];

  if ((gParams.modelType == TIDL_IMPORT_MODEL_FORMAT_CAFFE || gParams.modelType == TIDL_IMPORT_MODEL_FORMAT_TENSORFLOW || gParams.modelType == TIDL_IMPORT_MODEL_FORMAT_ONNX || gParams.modelType == TIDL_IMPORT_MODEL_FORMAT_TFLITE) &&
      (TIDLPCLayerOut.layerType == TIDL_InnerProductLayer && (TIDLPCLayerOut.layerPCParams.innerProductParams.isGemm == 1 || TIDLPCLayerOut.numInBufs < 2)) &&
      (TIDLPCLayers.outConsumerCnt[0] == 1))
  {
    if ((poolParams.poolingType == TIDL_AveragePooling) && (poolParams.kernelW == 0) && (poolParams.kernelH == 0))
    {
      TIDLPCLayers.outData[0].dimValues[TIDL_DIM_WIDTH] = TIDLPCLayers.outData[0].dimValues[TIDL_DIM_NUMCH] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_HEIGHT] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_WIDTH];
      TIDLPCLayers.outData[0].dimValues[TIDL_DIM_HEIGHT] = 1;
      TIDLPCLayers.outData[0].dimValues[TIDL_DIM_NUMCH] = 1;
    }
  }

  return TIDL_IMPORT_DIAGNOSIS_RETURN_OK;
}

int32_t TIDL_tfOutReshapeDeformConvLayer(sTIDL_OrgNetwork_t   *pOrgTIDLNetStructure, int32_t layerIndex)
{
  sTIDL_LayerPC_t &TIDLPCLayers = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex];
  sTIDL_DataParams_t *inDataParams[1] = { &TIDLPCLayers.inData[0] };
  TIDL_ShapeContext_t ctx;
  ctx.isCompileTime = 1;
  ctx.pcLayer       = (void *)&TIDLPCLayers;
  ctx.configParams  = (void *)&gParams;

  sTIDL_DeformConvParams_t &deformConvParams = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex].layerParams.deformConvParams;

  /*Default to signed*/
  TIDLPCLayers.outData[0].elementType = tidl_getElementType(1);

  if((TIDLPCLayers.actParams.actType == TIDL_RelU6) || (TIDLPCLayers.actParams.actType == TIDL_RelU) ||
    ((TIDLPCLayers.clipParams.isClipEnabled == 1) && (TIDLPCLayers.clipParams.clipMin >= 0)))
  {
    TIDLPCLayers.outData[0].elementType = tidl_getElementType(0);
  }
  TIDLPCLayers.outData[0].numDim = TIDLPCLayers.inData[0].numDim;

  TIDL_shapeInfer_DeformConv(&TIDLPCLayers.layerParams, inDataParams, 1, &TIDLPCLayers.outData[0], &ctx);

  TIDLPCLayers.numMacs =
    (int64_t)(((int64_t)TIDLPCLayers.outData[0].dimValues[TIDL_DIM_BATCH] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM1] *TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM2] *TIDLPCLayers.outData[0].dimValues[TIDL_DIM_NUMCH] *
      TIDLPCLayers.outData[0].dimValues[TIDL_DIM_HEIGHT] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_WIDTH] *
      deformConvParams.kernelW *deformConvParams.kernelH *
      TIDLPCLayers.inData[0].dimValues[TIDL_DIM_NUMCH]) / deformConvParams.numGroups);

  return 0;
}

int32_t TIDL_tfOutReshapeGridSampleLayer (sTIDL_OrgNetwork_t   *pOrgTIDLNetStructure, int32_t layerIndex)
{
  sTIDL_LayerPC_t &TIDLPCLayers = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex];
  sTIDL_DataParams_t *inDataParams[2] = { &TIDLPCLayers.inData[0], &TIDLPCLayers.inData[1] };
  TIDL_ShapeContext_t ctx;
  ctx.isCompileTime = 1;
  ctx.pcLayer       = (void *)&TIDLPCLayers;
  ctx.configParams  = (void *)&gParams;

  TIDLPCLayers.outData[0].elementType = TIDLPCLayers.inData[0].elementType;
  TIDLPCLayers.outData[0].numDim = TIDLPCLayers.inData[0].numDim;

  TIDL_shapeInfer_GridSample(&TIDLPCLayers.layerParams, inDataParams, 2, &TIDLPCLayers.outData[0], &ctx);

  /* Updating elementType of grid input */
  TIDLPCLayers.inData[1].elementType = TIDL_increasePrecision(TIDLPCLayers.inData[1].elementType);

  TIDLPCLayers.numMacs =
    (int64_t)((int64_t)TIDLPCLayers.outData[0].dimValues[TIDL_DIM_BATCH]* TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM1] *TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM2] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_NUMCH] *
      TIDLPCLayers.outData[0].dimValues[TIDL_DIM_HEIGHT] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_WIDTH]);

  return 0;
}

int32_t TIDL_tfOutReshapeCastLayer (sTIDL_OrgNetwork_t   *pOrgTIDLNetStructure, int32_t layerIndex)
{
  sTIDL_LayerPC_t &TIDLPCLayers = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex];
  sTIDL_DataParams_t *inDataParams[1] = { &TIDLPCLayers.inData[0] };
  TIDL_ShapeContext_t ctx;
  ctx.isCompileTime = 1;
  ctx.pcLayer       = (void *)&TIDLPCLayers;
  ctx.configParams  = (void *)&gParams;

  TIDLPCLayers.outData[0].elementType = TIDLPCLayers.layerPCParams.castParams.castTo;
  TIDLPCLayers.outData[0].numDim = TIDLPCLayers.inData[0].numDim;

  TIDL_shapeInfer_Cast(&TIDLPCLayers.layerParams, inDataParams, 1, &TIDLPCLayers.outData[0], &ctx);

  TIDLPCLayers.numMacs =
    (int64_t)((int64_t)TIDLPCLayers.outData[0].dimValues[TIDL_DIM_BATCH]* TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM1] *TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM2] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_NUMCH] *
      TIDLPCLayers.outData[0].dimValues[TIDL_DIM_HEIGHT] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_WIDTH]);

  return 0;
}

int32_t TIDL_tfOutReshapeIdentity(sTIDL_OrgNetwork_t   *pOrgTIDLNetStructure, int32_t layerIndex)
{
  sTIDL_LayerPC_t &TIDLPCLayers = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex];
  sTIDL_DataParams_t *inDataParams[1] = { &TIDLPCLayers.inData[0] };
  TIDL_ShapeContext_t ctx;
  ctx.isCompileTime = 1;
  ctx.pcLayer       = (void *)&TIDLPCLayers;
  ctx.configParams  = (void *)&gParams;

  if (TIDLPCLayers.layerType != TIDL_DataConvertLayer)
  {
    TIDLPCLayers.outData[0].elementType = TIDLPCLayers.inData[0].elementType;
  }

  TIDLPCLayers.outData[0].numDim = TIDLPCLayers.inData[0].numDim;

  TIDL_shapeInfer_PassThrough(&TIDLPCLayers.layerParams, inDataParams, 1, &TIDLPCLayers.outData[0], &ctx);

  TIDLPCLayers.numMacs =
    (int64_t)((int64_t)TIDLPCLayers.outData[0].dimValues[TIDL_DIM_BATCH]* TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM1] *TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM2] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_NUMCH] *
      TIDLPCLayers.outData[0].dimValues[TIDL_DIM_HEIGHT] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_WIDTH]);

  return 0;
}

int32_t TIDL_tfOutReshapeAttention(sTIDL_OrgNetwork_t   *pOrgTIDLNetStructure, int32_t layerIndex)
{
  sTIDL_LayerPC_t &TIDLPCLayers = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex];
  sTIDL_DataParams_t *inDataParams[3] = { &TIDLPCLayers.inData[0] , &TIDLPCLayers.inData[1] , &TIDLPCLayers.inData[2]};
  TIDL_ShapeContext_t ctx;
  ctx.isCompileTime = 1;
  ctx.pcLayer       = (void *)&TIDLPCLayers;
  ctx.configParams  = (void *)&gParams;

  TIDLPCLayers.outData[0].numDim = TIDLPCLayers.inData[0].numDim;

  TIDL_shapeInfer_Attention(&TIDLPCLayers.layerParams, inDataParams, TIDLPCLayers.numInBufs, &TIDLPCLayers.outData[0], &ctx);

  TIDLPCLayers.outData[0].elementType = TIDLPCLayers.inData[0].elementType;

  TIDLPCLayers.numMacs =
  (int64_t)((int64_t)TIDLPCLayers.outData[0].dimValues[TIDL_DIM_BATCH]* TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM1] *TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM2] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_NUMCH] *
    TIDLPCLayers.outData[0].dimValues[TIDL_DIM_HEIGHT] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_WIDTH]);


  return 0;
}

int32_t TIDL_tfOutReshapeGatherLayer(sTIDL_OrgNetwork_t   *pOrgTIDLNetStructure, int32_t layerIndex)
{
  sTIDL_LayerPC_t &layer = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex];
  int32_t numInBufs = layer.numInBufs > 0 ? layer.numInBufs : 1;
  sTIDL_DataParams_t *inDataParams[TIDL_NUM_IN_BUFS];
  for (int32_t b = 0; b < numInBufs; b++)
  {
    inDataParams[b] = &layer.inData[b];
  }
  TIDL_ShapeContext_t ctx;
  ctx.isCompileTime = 1;
  ctx.pcLayer       = (void *)&layer;
  ctx.configParams  = (void *)&gParams;

  layer.outData[0].numDim = layer.inData[0].numDim; // assuming grid is 1D

  TIDL_shapeInfer_Gather(&layer.layerParams, inDataParams, numInBufs, &layer.outData[0], &ctx);

  layer.outData[0].elementType = layer.inData[0].elementType;

  return 0;
}

int32_t TIDL_tfOutReshapeGatherNDLayer(sTIDL_OrgNetwork_t   *pOrgTIDLNetStructure, int32_t layerIndex)
{
  sTIDL_LayerPC_t &TIDLPCLayers = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex];
  sTIDL_DataParams_t *inDataParams[2] = { &TIDLPCLayers.inData[0], &TIDLPCLayers.inData[1] };
  TIDL_ShapeContext_t ctx;
  ctx.isCompileTime = 1;
  ctx.pcLayer       = (void *)&TIDLPCLayers;
  ctx.configParams  = (void *)&gParams;

  TIDL_shapeInfer_GatherND(&TIDLPCLayers.layerParams, inDataParams, 1, &TIDLPCLayers.outData[0], &ctx);
  
  TIDLPCLayers.outData[0].numDim = TIDLPCLayers.layerParams.gatherNDParams.outDimCount;
  
  TIDLPCLayers.outData[0].elementType = TIDLPCLayers.inData[0].elementType;
  return 0;
}


int32_t tidl_convertGatherNDToLineGatherND(sTIDL_OrgNetwork_t &pOrgTIDLNetStructure, int32_t numLayers, int32_t* dataIndex)
{
  /*
   * Insert a Reshape before a GatherND layer to convert it to a "line GatherND"
   * (i.e., gathering along the WIDTH dimension only).
   *
   * The last `remainder = numDims - origIndicesWidth` dimensions of the data
   * tensor are collapsed into a single new WIDTH value.  The leading
   * `numKept = TIDL_DIM_MAX - remainder` dimensions are shifted rightward into
   * the HEIGHT..DIM1 slots, with BATCH fixed to 1.
   *
   * TIDL layout:  BATCH(0) x DIM1(1) x DIM2(2) x NUMCH(3) x HEIGHT(4) x WIDTH(5)
   *
   * origIndicesWidth=1 (remainder=5):
   *   B x D1 x D2 x C x H x W  ->  1 x 1 x 1 x 1 x B x (D1*D2*C*H*W)
   *
   * origIndicesWidth=2 (remainder=4):
   *   B x D1 x D2 x C x H x W  ->  1 x 1 x 1 x B x D1 x (D2*C*H*W)
   *
   * origIndicesWidth=3 (remainder=3):
   *   B x D1 x D2 x C x H x W  ->  1 x 1 x B x D1 x D2 x (C*H*W)
   *
   * origIndicesWidth=4 (remainder=2):
   *   B x D1 x D2 x C x H x W  ->  1 x B x D1 x D2 x C x (H*W)
   */
  for (int32_t i = 0; i < numLayers; i++)
  {
    sTIDL_LayerPC_t &currLayer = pOrgTIDLNetStructure.TIDLPCLayers[i];
    if (currLayer.layerType != TIDL_GatherNDLayer)
    {
      continue;
    }

    int32_t numDims          = currLayer.layerParams.gatherNDParams.dataDimCount;
    int32_t batchDims          = currLayer.layerParams.gatherNDParams.batchDims;
    int32_t indicesLastDim = currLayer.inData[1].dimValues[TIDL_DIM_WIDTH];
    int32_t remainder        = numDims - indicesLastDim;

    /* remainder - batchDims <= 1: already a line GatherND — no transformation needed */
    if ((remainder - batchDims) <= 1)
    {
      continue;
    }

    int32_t stratIndex = TIDL_DIM_MAX - numDims + batchDims + indicesLastDim;
    /* Collapse the last `remainder` dimensions of data into a single WIDTH */
    int32_t newWidth = 1;
    int32_t totalDimsMerged = 0;
    for (int32_t j = stratIndex; j < TIDL_DIM_MAX; j++)
    {
      newWidth *= currLayer.inData[0].dimValues[j];
      totalDimsMerged += 1;
    }

    /*
     * Build the reshaped dimension array.
     */
    const int32_t numKept = TIDL_DIM_MAX - remainder + batchDims;

    int32_t newDataDimVals[TIDL_DIM_MAX];
    for (int32_t j = 0; j < TIDL_DIM_MAX; j++)
    {
      newDataDimVals[j] = 1;
    }
    newDataDimVals[TIDL_DIM_WIDTH] = newWidth;

    for (int32_t k = 0; k < numKept; k++)
    {
      newDataDimVals[TIDL_DIM_HEIGHT - numKept + 1 + k] = currLayer.inData[0].dimValues[k];
    }

    currLayer.layerParams.gatherNDParams.dataDimCount = numDims - totalDimsMerged + 1;
    currLayer.layerParams.gatherNDParams.outDimCount = currLayer.layerParams.gatherNDParams.outDimCount - totalDimsMerged + 1;

    std::vector<int32_t> inpNodeIndices = {0}; /* add reshape before the data input (index 0) */
    TIDL_wrapWithReshape(pOrgTIDLNetStructure, i, dataIndex, newDataDimVals, inpNodeIndices);
  }

  return TIDL_IMPORT_DIAGNOSIS_RETURN_OK;
}

int32_t TIDL_tfOutReshapeGatherElementsLayer(sTIDL_OrgNetwork_t   *pOrgTIDLNetStructure, int32_t layerIndex)
{
  sTIDL_LayerPC_t &TIDLPCLayers = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex];
  sTIDL_DataParams_t *inDataParams[1] = { &TIDLPCLayers.inData[1] };
  TIDL_ShapeContext_t ctx;
  ctx.isCompileTime = 1;
  ctx.pcLayer       = (void *)&TIDLPCLayers;
  ctx.configParams  = (void *)&gParams;

  TIDL_shapeInfer_GatherElements(&TIDLPCLayers.layerParams, inDataParams, 1, &TIDLPCLayers.outData[0], &ctx);

  TIDLPCLayers.outData[0].elementType = TIDLPCLayers.inData[0].elementType;
  TIDLPCLayers.outData[0].numDim = TIDLPCLayers.inData[1].numDim;

  return 0;
}

int32_t TIDL_tfOutReshapeTransposeLayer(sTIDL_OrgNetwork_t   *pOrgTIDLNetStructure, int32_t layerIndex)
{
  sTIDL_LayerPC_t &TIDLPCLayers = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex];
  sTIDL_DataParams_t *inDataParams[1] = { &TIDLPCLayers.inData[0] };
  TIDL_ShapeContext_t ctx;
  ctx.isCompileTime = 1;
  ctx.pcLayer       = (void *)&TIDLPCLayers;
  ctx.configParams  = (void *)&gParams;

  TIDLPCLayers.outData[0].elementType = TIDLPCLayers.inData[0].elementType;
  TIDLPCLayers.inData[0].numDim = TIDLPCLayers.weights.bufSize;
  TIDLPCLayers.outData[0].numDim = TIDLPCLayers.weights.bufSize;

  TIDL_shapeInfer_Transpose(&TIDLPCLayers.layerParams, inDataParams, 1, &TIDLPCLayers.outData[0], &ctx);

  TIDLPCLayers.numMacs =
    (int64_t)((int64_t)TIDLPCLayers.outData[0].dimValues[TIDL_DIM_BATCH] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM1] *TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM2]* TIDLPCLayers.outData[0].dimValues[TIDL_DIM_NUMCH] *
      TIDLPCLayers.outData[0].dimValues[TIDL_DIM_HEIGHT] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_WIDTH]);
  return 0;
}

int32_t TIDL_tfOutReshapeNonZeroLayer(sTIDL_OrgNetwork_t   *pOrgTIDLNetStructure, int32_t layerIndex)
{
  sTIDL_LayerPC_t &TIDLPCLayers = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex];
  sTIDL_DataParams_t *inDataParams[1] = { &TIDLPCLayers.inData[0] };
  TIDL_ShapeContext_t ctx;
  ctx.isCompileTime = 1;
  ctx.pcLayer       = (void *)&TIDLPCLayers;
  ctx.configParams  = (void *)&gParams;

  TIDLPCLayers.outData[0].elementType = TIDL_SignedWord;

  TIDL_shapeInfer_NonZero(&TIDLPCLayers.layerParams, inDataParams, 1, &TIDLPCLayers.outData[0], &ctx);

  TIDLPCLayers.numMacs =
    (int64_t)((int64_t)TIDLPCLayers.outData[0].dimValues[TIDL_DIM_BATCH] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM1] *TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM2]* TIDLPCLayers.outData[0].dimValues[TIDL_DIM_NUMCH] *
      TIDLPCLayers.outData[0].dimValues[TIDL_DIM_HEIGHT] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_WIDTH]);

  return 0;
}

int32_t TIDL_tfOutReshapeTopKLayer (sTIDL_OrgNetwork_t   *pOrgTIDLNetStructure, int32_t layerIndex)
{
  sTIDL_LayerPC_t &TIDLPCLayers = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex];
  int32_t axis = TIDLPCLayers.layerParams.topKParams.axis;
  int32_t K    = TIDLPCLayers.layerParams.topKParams.K;
  sTIDL_DataParams_t *inDataParams[1] = { &TIDLPCLayers.inData[0] };
  TIDL_ShapeContext_t ctx;
  ctx.isCompileTime = 1;
  ctx.pcLayer       = (void *)&TIDLPCLayers;
  ctx.configParams  = (void *)&gParams;

  TIDLPCLayers.outData[0].elementType = TIDLPCLayers.inData[0].elementType;

  memcpy (&TIDLPCLayers.outData[0].dimValues, &TIDLPCLayers.inData[0].dimValues, sizeof(int32_t) * TIDL_DIM_MAX);
  memcpy (&TIDLPCLayers.outData[1].dimValues, &TIDLPCLayers.inData[0].dimValues, sizeof(int32_t) * TIDL_DIM_MAX);
  TIDLPCLayers.outData[0].dimValues[axis] = K;
  TIDLPCLayers.outData[1].dimValues[axis] = K;

  if (TIDLPCLayers.layerPCParams.topKParams.isAxisHandled == 1)
  {
    /**
     * We combine both the outputs to a single output with an increased buffer size
     */
    TIDLPCLayers.layerParams.topKParams.incrementAxis = tidl_getAxisForTopKOutputBuffer (TIDLPCLayers);
  
    TIDL_shapeInfer_TopK(&TIDLPCLayers.layerParams, inDataParams, 1, &TIDLPCLayers.outData[0], &ctx);
    if (TIDLPCLayers.numOutBufs > 1)
    {
      TIDL_shapeInfer_TopK(&TIDLPCLayers.layerParams, inDataParams, 1, &TIDLPCLayers.outData[1], &ctx);
    }

    TIDLPCLayers.numMacs =
      (int64_t)((int64_t)TIDLPCLayers.outData[0].dimValues[TIDL_DIM_BATCH] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM1] *TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM2]* TIDLPCLayers.outData[0].dimValues[TIDL_DIM_NUMCH] *
        TIDLPCLayers.outData[0].dimValues[TIDL_DIM_HEIGHT] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_WIDTH]);
  }

  return 0;
}

