int32_t TIDL_tfOutReshapeReshapeLayer(sTIDL_OrgNetwork_t   *pOrgTIDLNetStructure, int32_t layerIndex)
{
  sTIDL_LayerPC_t &TIDLPCLayers = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex];

  if (TIDLPCLayers.layerPCParams.reshapeParams.isReInterpret != 1)
  {
    TIDLPCLayers.outData[0].elementType = TIDLPCLayers.inData[0].elementType;
  }

  if (TIDLPCLayers.layerPCParams.reshapeParams.isInduced != 0)
  {
    /** Reshape layer introduces by TIDL, should would already be updated, don't update shape*/
    return 0;
  }

  TIDLPCLayers.outData[0].numDim = TIDLPCLayers.inData[0].numDim;

  int32_t i, remDim=0, dim=0, startIdx = 0;
  int32_t weights[TIDL_DIM_MAX];
  for(i = 0; i < TIDLPCLayers.weights.bufSize; i++)
  {
    weights[i] = ((int32_t*)(TIDLPCLayers.weights.ptr))[i];
  }

  int32_t* outData = TIDLPCLayers.outData[0].dimValues;
  int32_t* inData = TIDLPCLayers.inData[0].dimValues;

  // Handle 0 and -1
  int32_t  bufSizeW  = TIDLPCLayers.weights.bufSize;
  int32_t  remDimW   = TIDL_DIM_MAX - bufSizeW;
  int32_t  allowZero = TIDLPCLayers.layerPCParams.reshapeParams.allowZero;
  uint64_t totalSize = 1;
  for (int32_t k = 0; k < TIDL_DIM_MAX; k++)
  {
    totalSize *= inData[k];
  }

  uint64_t partialSize = 1;
  int32_t  negIdx = -1;
  for (int32_t j = 0; j < bufSizeW; j++)
  {
    if (weights[j] == 0 && allowZero == 0)
    {
      weights[j] = inData[remDimW + j];
      partialSize *= weights[j];
    }
    else if (weights[j] == -1)
    {
      negIdx = j;
    }
    else
    {
      partialSize *= weights[j];
    }
  }
  if (negIdx != -1)
  {
    weights[negIdx] = (int32_t)(totalSize / partialSize);
  }

  /* Write resolved values back so weights.ptr reflects concrete dims */
  for (int32_t j = 0; j < TIDLPCLayers.weights.bufSize; j++)
  {
    ((int32_t*)(TIDLPCLayers.weights.ptr))[j] = weights[j];
  }

  // Update the output shapes
  if (TIDLPCLayers.weights.bufSize == TIDL_DIM_MAX)
  {
    for (int32_t i = 0; i < TIDLPCLayers.weights.bufSize; i++)
    {
      outData[i] = weights[i];
    }
  }
  else
  {
    if (inData[TIDL_DIM_BATCH] != 1)
    {
      int32_t canInheritBatch = 0;
      /* respect batch in case of HighThroughput mode or (gParams.numBatches has been set in TIDL-RT import config) or (gParams.numBatches is set and batch
         dimension is constant in input and output shape if running through OSRT ) */
      if(gParams.inferenceMode == TIDL_inferenceModeHighThroughput)
      {
        canInheritBatch = 1;
      }
      else
      {
        if(inData[TIDL_DIM_BATCH] == gParams.numBatches[0] &&
           gParams.modelType != TIDL_IMPORT_MODEL_FORMAT_TFLITE_RT &&
           gParams.modelType != TIDL_IMPORT_MODEL_FORMAT_ONNX_RT  &&
           gParams.modelType != TIDL_IMPORT_MODEL_FORMAT_TVM_RELAY)
        {
          canInheritBatch = 1;
        }
        /* Check for batch in reshape weights */
        else if(TIDLPCLayers.isBatchGroupLayer == 1)
        {
          int32_t inVolume = 1;
          int32_t outVolume = 1;
          for(int32_t j = TIDL_DIM_BATCH; j < TIDL_DIM_MAX; j++)
          {
            inVolume *= inData[j];
          }
          for(int32_t j = 0; j < TIDLPCLayers.weights.bufSize; j++)
          {
            outVolume *= weights[j];
          }
          if(inVolume != outVolume)
          {
            TIDL_GLOBAL_REPORT_ERROR("Input volume should be equal to output volume for Reshape layer - %s", TIDLPCLayers.name);
            return TIDL_IMPORT_DIAGNOSIS_RETURN_FAIL;
          }
          if(inData[TIDL_DIM_BATCH] == weights[startIdx])
          {
            canInheritBatch = 1;
          }
        }
      }

      if(canInheritBatch == 1)
      {
        outData[TIDL_DIM_BATCH] = inData[TIDL_DIM_BATCH];
        dim = 1;
        startIdx = 1;
      }
    }

    remDim = TIDL_DIM_MAX - TIDLPCLayers.weights.bufSize;

    for (int32_t i=0;i<remDim;i++)
    {
      outData[dim++] = 1;
    }

    for (int32_t i=startIdx;i<TIDLPCLayers.weights.bufSize;i++)
    {
      outData[dim++] = weights[i];
    }
  }

  int32_t notOne = 0, notOneIndex = 0, idx=0;
  for (int32_t i=1;i<TIDL_DIM_MAX;i++)
  {
    if (TIDLPCLayers.outData[0].dimValues[i] != 1)
    {
      notOne++;
      notOneIndex = i;
    }
  }
  idx = tidl_getOutLayer(pOrgTIDLNetStructure, pOrgTIDLNetStructure->numLayers, TIDLPCLayers.outData[0].dataId);
  
  // Flatten only if 1D softmax or innerproduct (non act x act) in case of tidl-rt imported models
  if(((gParams.modelType == TIDL_IMPORT_MODEL_FORMAT_CAFFE || gParams.modelType == TIDL_IMPORT_MODEL_FORMAT_TENSORFLOW || gParams.modelType == TIDL_IMPORT_MODEL_FORMAT_ONNX || gParams.modelType == TIDL_IMPORT_MODEL_FORMAT_TFLITE)) &&
     (notOne == 1) &&
     (pOrgTIDLNetStructure->TIDLPCLayers[idx].layerType == TIDL_SoftMaxLayer ||
      (pOrgTIDLNetStructure->TIDLPCLayers[idx].layerType == TIDL_InnerProductLayer && pOrgTIDLNetStructure->TIDLPCLayers[idx].allowlistingMetaData.numVarInputs < 2))
    )
  {
    //If the input is flattened and the next layer is softmax, shift the flattened dimension to width dimension
    TIDLPCLayers.outData[0].dimValues[TIDL_DIM_WIDTH] = TIDLPCLayers.outData[0].dimValues[notOneIndex];
    TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM1]=1;
    TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM2]=1;
    TIDLPCLayers.outData[0].dimValues[TIDL_DIM_NUMCH] = 1;
    TIDLPCLayers.outData[0].dimValues[TIDL_DIM_HEIGHT] = 1;
  }

  /*Check if any output dimension is not set correctly:*/
  for(i = 0; i < TIDL_DIM_MAX ; i++)
  {
    /*If any dimension is 0 or lesser, an error has occured:*/
    if(TIDLPCLayers.outData[0].dimValues[i]  <= 0)
    {
      TIDL_GLOBAL_REPORT_ERROR("Reshape %s : unable to determine output dimension for dimension %d\n", TIDLPCLayers.outDataNames[0], i);
      return TIDL_IMPORT_DIAGNOSIS_RETURN_FAIL;
    }
  }

  /*Reshape has no compute:*/
  TIDLPCLayers.numMacs = 0;

  return 0;
}

int32_t TIDL_tfOutReshapeEltwise(sTIDL_OrgNetwork_t   *pOrgTIDLNetStructure, int32_t layerIndex)
{
  sTIDL_LayerPC_t &TIDLPCLayers = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex];
  int32_t numInBufs = TIDLPCLayers.numInBufs > 0 ? TIDLPCLayers.numInBufs : 1;
  sTIDL_DataParams_t *inDataParams[TIDL_NUM_IN_BUFS];
  for (int32_t b = 0; b < numInBufs; b++)
  {
    inDataParams[b] = &TIDLPCLayers.inData[b];
  }
  TIDL_ShapeContext_t ctx;
  ctx.isCompileTime = 1;
  ctx.pcLayer       = (void *)&TIDLPCLayers;
  ctx.configParams  = (void *)&gParams;
 
  TIDL_shapeInfer_EltWise(&TIDLPCLayers.layerParams, inDataParams, numInBufs, &TIDLPCLayers.outData[0], &ctx);

  TIDLPCLayers.outData[0].numDim = 0;
  for (int32_t i = 0; i < numInBufs; i++)
  {
    TIDLPCLayers.outData[0].numDim = std::max(TIDLPCLayers.outData[0].numDim, TIDLPCLayers.inData[i].numDim);
  }

  TIDLPCLayers.numMacs =
    (int64_t)((int64_t)TIDLPCLayers.outData[0].dimValues[TIDL_DIM_BATCH] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM1] *TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM2]* TIDLPCLayers.outData[0].dimValues[TIDL_DIM_NUMCH] *
      TIDLPCLayers.outData[0].dimValues[TIDL_DIM_HEIGHT] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_WIDTH]);

  TIDLPCLayers.outData[0].elementType = tidl_getElementType(0);
  for (int32_t j = 0; j < TIDLPCLayers.numInBufs; j++)
  {
    if ((TIDLPCLayers.inData[j].elementType == TIDL_SignedChar) ||
        (TIDLPCLayers.inData[j].elementType == TIDL_SignedShort))
    {
      TIDLPCLayers.outData[0].elementType = tidl_getElementType(1);
    }
  }
  if((TIDLPCLayers.actParams.actType == TIDL_RelU6) || (TIDLPCLayers.actParams.actType == TIDL_RelU) ||
     (TIDLPCLayers.clipParams.isClipEnabled == 1 && TIDLPCLayers.clipParams.clipMin >= 0))
  {
    TIDLPCLayers.outData[0].elementType = tidl_getElementType(0);
  }

  /** Only EltWise_Mod supports int32 data type */
  if ((TIDLPCLayers.inData[0].elementType == TIDL_SignedWord ||
       TIDLPCLayers.inData[1].elementType == TIDL_SignedWord) &&
       TIDLPCLayers.layerParams.eltWiseParams.eltWiseType == TIDL_EltWiseMod)
  {
    TIDLPCLayers.outData[0].elementType = TIDL_SignedWord;
  }
  return 0;
}

int32_t TIDL_tfOutReshapePRelu(sTIDL_OrgNetwork_t   *pOrgTIDLNetStructure, int32_t layerIndex)
{
  sTIDL_LayerPC_t &TIDLPCLayers = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex];
  sTIDL_DataParams_t *inDataParams[1] = { &TIDLPCLayers.inData[0] };
  TIDL_ShapeContext_t ctx;
  ctx.isCompileTime = 1;
  ctx.pcLayer       = (void *)&TIDLPCLayers;
  ctx.configParams  = (void *)&gParams;

  TIDLPCLayers.outData[0].elementType = tidl_getElementType(1);
  TIDLPCLayers.layerParams.batchNormParams.numChannels = TIDLPCLayers.inData[0].dimValues[TIDL_DIM_NUMCH];
  TIDLPCLayers.outData[0].numDim = TIDLPCLayers.inData[0].numDim;

  TIDL_shapeInfer_BatchNorm(&TIDLPCLayers.layerParams, inDataParams, 1, &TIDLPCLayers.outData[0], &ctx);

  TIDLPCLayers.numMacs =
    (int64_t)((int64_t)TIDLPCLayers.outData[0].dimValues[TIDL_DIM_BATCH]* TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM1] *TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM2] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_NUMCH] *
      TIDLPCLayers.outData[0].dimValues[TIDL_DIM_HEIGHT] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_WIDTH]);

  /*
  * Handle Random Coeff case
  */
  int32_t dataSize = TIDLPCLayers.layerParams.batchNormParams.numChannels;

  if(TIDLPCLayers.slope.ptr == NULL)
  {
    TIDL_GLOBAL_REPORT_WARNING("PReLU Layer %s's slope cannot be found(or not match) in coeff file, "
           "Random slope will be generated "
           "only for evaluation usage. "
           "Results are all random", TIDLPCLayers.name);

    float * slope = (float*)my_malloc(dataSize*sizeof(float));
    for (int j = 0; j < dataSize; j++)
    {
      slope[j] = 1;
    }

    TIDLPCLayers.slope.ptr = slope;
    TIDLPCLayers.slope.bufSize = dataSize;
  }
  else if(TIDLPCLayers.slope.bufSize != dataSize)
  {
    /* Broadcast case, when the slope is a single value and we need to broadcast it across all channels
     * Non-broadcastable case is denied in allowlisting
     */
    float *slopePtr = (float *)TIDLPCLayers.slope.ptr;
    float slopeValue = slopePtr[0];
    float *newSlope = (float*)my_malloc(dataSize*sizeof(float));
    for (int j = 0; j < dataSize; j++)
    {
      newSlope[j] = slopeValue;
    }

    my_free(TIDLPCLayers.slope.ptr);
    TIDLPCLayers.slope.ptr = newSlope;
    TIDLPCLayers.slope.bufSize = dataSize;
  }

  return 0;
}

int32_t tidl_doesBatchNormSatisfyBatchConstraints (sTIDL_LayerPC_t &TIDLPCLayers)
{
  int32_t dataSize = TIDLPCLayers.layerParams.batchNormParams.numChannels;
  int32_t batchConstraints = 0;
  /**
   * This case is handling when channel dimension is moved to batch dimension during batch processing
  */
  if (TIDLPCLayers.bias.ptr != NULL && TIDLPCLayers.bias.bufSize != dataSize ||
      TIDLPCLayers.weights.ptr != NULL && TIDLPCLayers.weights.bufSize != dataSize)
  {
    batchConstraints  = ((dataSize == 1 && TIDLPCLayers.inData[0].dimValues[TIDL_DIM_BATCH] != 1) && 
                        (TIDLPCLayers.bias.bufSize == TIDLPCLayers.inData[0].dimValues[TIDL_DIM_BATCH]) &&
                        (TIDLPCLayers.weights.bufSize == TIDLPCLayers.inData[0].dimValues[TIDL_DIM_BATCH]));
  }
  
  return batchConstraints;
}

int32_t TIDL_tfOutReshapeBN(sTIDL_OrgNetwork_t   *pOrgTIDLNetStructure, int32_t layerIndex)
{
  sTIDL_LayerPC_t &TIDLPCLayers = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex];
  sTIDL_DataParams_t *inDataParams[1] = { &TIDLPCLayers.inData[0] };
  TIDL_ShapeContext_t ctx;
  ctx.isCompileTime = 1;
  ctx.pcLayer       = (void *)&TIDLPCLayers;
  ctx.configParams  = (void *)&gParams;

  TIDLPCLayers.outData[0].elementType =  tidl_getElementType(1);
  TIDLPCLayers.outData[0].numDim = TIDLPCLayers.inData[0].numDim;

  TIDL_shapeInfer_BatchNorm(&TIDLPCLayers.layerParams, inDataParams, 1, &TIDLPCLayers.outData[0], &ctx);

  TIDLPCLayers.numMacs =
    (int64_t)((int64_t)TIDLPCLayers.outData[0].dimValues[TIDL_DIM_BATCH]* TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM1] *TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM2] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_NUMCH] *
      TIDLPCLayers.outData[0].dimValues[TIDL_DIM_HEIGHT] * TIDLPCLayers.outData[0].dimValues[TIDL_DIM_WIDTH]);

  sTIDL_allowlistingMetaData& md = TIDLPCLayers.allowlistingMetaData;
  int32_t numChannels;
  if((md.varTensorsDims.size() > 0 && md.varTensorsDims[0].size() > 0) && TIDLPCLayers.actParams.actType == TIDL_NoAct && 
      TIDLPCLayers.isConverted == 0 && TIDLPCLayers.clipParams.isClipEnabled == 0)
  {
    /* Use metadata if present */
    if(md.varTensorsDims[0].size() > 1)
    {
      numChannels = md.varTensorsDims[0][1];
    }
    else
    {
      numChannels = 1;
    }
  }
  else
  {
    numChannels = TIDLPCLayers.inData[0].dimValues[TIDL_DIM_NUMCH];
  }

  TIDLPCLayers.layerParams.batchNormParams.numChannels = numChannels;

  if((TIDLPCLayers.actParams.actType == TIDL_RelU6) || (TIDLPCLayers.actParams.actType == TIDL_RelU)||
    (TIDLPCLayers.actParams.actType == TIDL_Sigmoid) ||
    ((TIDLPCLayers.clipParams.isClipEnabled == 1) && (TIDLPCLayers.clipParams.clipMin >= 0)))
  {
    TIDLPCLayers.outData[0].elementType = tidl_getElementType(0);
  }

  /*
  * Handle Random Coeff case
  */
  int32_t dataSize = TIDLPCLayers.layerParams.batchNormParams.numChannels;

  if(TIDLPCLayers.bias.ptr == NULL ||
     TIDLPCLayers.bias.bufSize !=  dataSize ||
     TIDLPCLayers.weights.ptr == NULL ||
     TIDLPCLayers.weights.bufSize != dataSize)
  {
    int32_t batchConstraints = tidl_doesBatchNormSatisfyBatchConstraints (TIDLPCLayers);

    if (batchConstraints != 1 && TIDLPCLayers.actParams.actType != TIDL_Logit && TIDLPCLayers.actParams.actType != TIDL_Reciprocal && TIDLPCLayers.actParams.actType != TIDL_SiLU && TIDLPCLayers.actParams.actType != TIDL_Swish)
    {
      TIDL_GLOBAL_REPORT_WARNING("Batch Norm Layer %s's coeff cannot be found(or not match) in coeff file, "
            "Random bias will be generated "
            "only for evaluation usage. "
            "Results are all random\n", TIDLPCLayers.name);

      float * weights = (float*)my_malloc(dataSize*sizeof(float));
      float * bias = (float*)my_malloc(dataSize*sizeof(float));
      for (int j = 0; j < dataSize; j++)
      {
        weights[j] = 1;
        bias[j]  = 0;
      }

      if(TIDLPCLayers.bias.ptr == NULL || TIDLPCLayers.bias.bufSize !=  dataSize)
      {
        TIDLPCLayers.bias.ptr = bias;
        TIDLPCLayers.bias.bufSize = dataSize;
      }
      if(TIDLPCLayers.weights.ptr == NULL || TIDLPCLayers.weights.bufSize != dataSize)
      {
        TIDLPCLayers.weights.ptr = weights;
        TIDLPCLayers.weights.bufSize = dataSize;
      }
    }
  }

  return 0;
}


