int32_t TIDL_tfOutReshapeScatterElementsLayer(sTIDL_OrgNetwork_t   *pOrgTIDLNetStructure, int32_t layerIndex)
{
  sTIDL_LayerPC_t &TIDLPCLayers = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex];
  int32_t dataTensorId = 0;
  int32_t i,j,k;
  int32_t minDim;

  int32_t axis = TIDLPCLayers.layerParams.scatterElementsParams.axis;
  int32_t isScatterNd = (axis == -1)?1:0;

  if(isScatterNd)
  {
    int8_t dataIsVar = 0;
    int8_t indIsVar = 0;
    sTIDL_allowlistingMetaData md = TIDLPCLayers.allowlistingMetaData;
    for (i = 0; i < md.varTensorIndices.size(); i++)
    {
      if (md.varTensorIndices[i] == 0)
      {
        dataIsVar = 1;
      }
      if (md.varTensorIndices[i] == 1)
      {
        indIsVar = 1;
      }
    }

    int32_t dataDim;
    int32_t indSize;
    int32_t indDim;

    // Both data and indices are variable
    if(dataIsVar && indIsVar)
    {
      dataDim = TIDLPCLayers.allowlistingMetaData.varTensorsDims[0].size();
      indSize = TIDLPCLayers.allowlistingMetaData.varTensorsDims[1].size();
      indDim = TIDLPCLayers.allowlistingMetaData.varTensorsDims[1][indSize-1];
    }

    // Data is variable and indices is constant
    else if (dataIsVar && !indIsVar)
    {
      dataDim = TIDLPCLayers.allowlistingMetaData.varTensorsDims[0].size();
      indSize = TIDLPCLayers.allowlistingMetaData.constTensorsDims[0].size();
      indDim = TIDLPCLayers.allowlistingMetaData.constTensorsDims[0][indSize-1];
    }

    // Data is constant and indices is variable
    else if (!dataIsVar && indIsVar)
    {
      dataDim = TIDLPCLayers.allowlistingMetaData.constTensorsDims[0].size();
      indSize = TIDLPCLayers.allowlistingMetaData.varTensorsDims[0].size();
      indDim = TIDLPCLayers.allowlistingMetaData.varTensorsDims[0][indSize-1];
    }
    
    // Both data and indices are constant
    else
    {
      dataDim = TIDLPCLayers.allowlistingMetaData.constTensorsDims[0].size();
      indSize = TIDLPCLayers.allowlistingMetaData.constTensorsDims[1].size();
      indDim = TIDLPCLayers.allowlistingMetaData.constTensorsDims[1][indSize-1];
    }

    if (dataDim == 0)
    {
      if (indDim == 4) {TIDLPCLayers.inData[0].numDim = 4;}
      else if (indDim == 2) {TIDLPCLayers.inData[0].numDim = 3;}
      else if (indDim == 1) {TIDLPCLayers.inData[0].numDim = 2;}
    }
    else
    {
      TIDLPCLayers.inData[0].numDim = dataDim;
    }
    TIDLPCLayers.outData[0].numDim = TIDLPCLayers.inData[0].numDim;
  }

  TIDLPCLayers.outData[0].elementType = tidl_getElementType(1);

  TIDLPCLayers.outData[0].dimValues[TIDL_DIM_BATCH] = TIDLPCLayers.inData[0].dimValues[TIDL_DIM_BATCH];
  TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM1] = TIDLPCLayers.inData[0].dimValues[TIDL_DIM_DIM1];
  TIDLPCLayers.outData[0].dimValues[TIDL_DIM_DIM2] = TIDLPCLayers.inData[0].dimValues[TIDL_DIM_DIM2];
  TIDLPCLayers.outData[0].dimValues[TIDL_DIM_NUMCH] = TIDLPCLayers.inData[0].dimValues[TIDL_DIM_NUMCH];
  TIDLPCLayers.outData[0].dimValues[TIDL_DIM_HEIGHT] = TIDLPCLayers.inData[0].dimValues[TIDL_DIM_HEIGHT];
  TIDLPCLayers.outData[0].dimValues[TIDL_DIM_WIDTH] = TIDLPCLayers.inData[0].dimValues[TIDL_DIM_WIDTH];

  return 0;
}

int32_t TIDL_tfOutReshapeLSTMLayer(sTIDL_OrgNetwork_t *pOrgTIDLNetStructure, int32_t layerIndex)
{
  sTIDL_LayerPC_t &TIDLPCLayers = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex];
  sTIDL_LSTMParams_t &lstmParams = TIDLPCLayers.layerParams.lstmParams;
  sTIDL_LSTMPCParams_t &lstmPCParams = TIDLPCLayers.layerPCParams.lstmParams;
  sTIDL_DataParams_t *inDataParams[1] = { &TIDLPCLayers.inData[0] };
  TIDL_ShapeContext_t ctx;
  ctx.isCompileTime = 1;
  ctx.pcLayer       = (void *)&TIDLPCLayers;
  ctx.configParams  = (void *)&gParams;

  for(int32_t outBufIdx = 0; outBufIdx < TIDLPCLayers.numOutBufs; outBufIdx++)
  {
    TIDLPCLayers.outData[outBufIdx].elementType = TIDLPCLayers.inData[0].elementType;

    for(int32_t dimIdx = TIDL_DIM_BATCH; dimIdx < TIDL_DIM_MAX; dimIdx++)
    {
      TIDLPCLayers.outData[outBufIdx].dimValues[dimIdx] = TIDLPCLayers.inData[0].dimValues[dimIdx];
    }
  }

  int32_t seq_length, batch_size;
  if (lstmParams.layout == 0)
  {
    /* input shape: [seq_length, batch_size, input_size] */
    seq_length = TIDLPCLayers.inData[0].dimValues[TIDL_DIM_NUMCH];
    batch_size = TIDLPCLayers.inData[0].dimValues[TIDL_DIM_HEIGHT];
  }
  else
  {
    /* input shape: [batch_size, seq_length, input_size] */
    seq_length = TIDLPCLayers.inData[0].dimValues[TIDL_DIM_HEIGHT];
    batch_size = TIDLPCLayers.inData[0].dimValues[TIDL_DIM_NUMCH];
  }

  int32_t hidden_size = lstmParams.hidden_size;
  int32_t num_directions = 1;
  if(lstmParams.direction == TIDL_RecurrentBidirectional)
  {
    num_directions = 2;
  }

  for(int32_t outBufIdx = 0; outBufIdx < TIDLPCLayers.numOutBufs; outBufIdx++)
  {
    if(lstmParams.layout == 0)
    {
      if(outBufIdx == 0)
      {
        /* output shape: [seq_length, num_directions, batch_size, hidden_size] */
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_DIM2]   = seq_length;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_NUMCH]  = num_directions;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_HEIGHT] = batch_size;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_WIDTH]  = hidden_size;
      }
      else
      {
        /* output shape: [1, num_directions, batch_size, hidden_size] */
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_DIM2]   = 1;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_NUMCH]  = num_directions;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_HEIGHT] = batch_size;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_WIDTH]  = hidden_size;
      }
    }
    else
    {
      if(outBufIdx == 0)
      {
        /* output shape: [batch_size, seq_length, num_directions, hidden_size] */
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_DIM2]   = batch_size;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_NUMCH]  = seq_length;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_HEIGHT] = num_directions;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_WIDTH]  = hidden_size;
      }
      else
      {
        /* output shape: [batch_size, 1, num_directions, hidden_size] */
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_DIM2]   = batch_size;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_NUMCH]  = 1;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_HEIGHT] = num_directions;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_WIDTH]  = hidden_size;
      }
    }
  }

  /**
   * Combine all the outputs to a single output with an increased buffer size
   * This is the final size of the lstm layer (i.e the runtime shape)
   */
  if(lstmPCParams.isOutputSliced == 1)
  {
    for(int32_t outBufIdx = 0; outBufIdx < TIDLPCLayers.numOutBufs; outBufIdx++)
    {
      TIDL_shapeInfer_LSTM(&TIDLPCLayers.layerParams, inDataParams, 1, &TIDLPCLayers.outData[outBufIdx], &ctx);
    }
  }

  return 0;
}

int32_t TIDL_tfOutReshapeGRULayer(sTIDL_OrgNetwork_t *pOrgTIDLNetStructure, int32_t layerIndex)
{
  sTIDL_LayerPC_t &TIDLPCLayers = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex];
  sTIDL_GRUParams_t &gruParams = TIDLPCLayers.layerParams.gruParams;
  sTIDL_GRUPCParams_t &gruPCParams = TIDLPCLayers.layerPCParams.gruParams;
  sTIDL_DataParams_t *inDataParams[1] = { &TIDLPCLayers.inData[0] };
  TIDL_ShapeContext_t ctx;
  ctx.isCompileTime = 1;
  ctx.pcLayer       = (void *)&TIDLPCLayers;
  ctx.configParams  = (void *)&gParams;

  for(int32_t outBufIdx = 0; outBufIdx < TIDLPCLayers.numOutBufs; outBufIdx++)
  {
    TIDLPCLayers.outData[outBufIdx].elementType = TIDLPCLayers.inData[0].elementType;

    for(int32_t dimIdx = TIDL_DIM_BATCH; dimIdx < TIDL_DIM_MAX; dimIdx++)
    {
      TIDLPCLayers.outData[outBufIdx].dimValues[dimIdx] = TIDLPCLayers.inData[0].dimValues[dimIdx];
    }
  }

  int32_t seq_length, batch_size;
  if (gruParams.layout == 0)
  {
    /* input shape: [seq_length, batch_size, input_size] */
    seq_length = TIDLPCLayers.inData[0].dimValues[TIDL_DIM_NUMCH];
    batch_size = TIDLPCLayers.inData[0].dimValues[TIDL_DIM_HEIGHT];
  }
  else
  {
    /* input shape: [batch_size, seq_length, input_size] */
    seq_length = TIDLPCLayers.inData[0].dimValues[TIDL_DIM_HEIGHT];
    batch_size = TIDLPCLayers.inData[0].dimValues[TIDL_DIM_NUMCH];
  }

  int32_t hidden_size = gruParams.hidden_size;
  int32_t num_directions = 1;
  if(gruParams.direction == TIDL_RecurrentBidirectional)
  {
    num_directions = 2;
  }

  for(int32_t outBufIdx = 0; outBufIdx < TIDLPCLayers.numOutBufs; outBufIdx++)
  {
    if(gruParams.layout == 0)
    {
      if(outBufIdx == 0)
      {
        /* output shape: [seq_length, num_directions, batch_size, hidden_size] */
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_DIM2]   = seq_length;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_NUMCH]  = num_directions;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_HEIGHT] = batch_size;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_WIDTH]  = hidden_size;
      }
      else
      {
        /* output shape: [1, num_directions, batch_size, hidden_size] */
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_DIM2]   = 1;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_NUMCH]  = num_directions;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_HEIGHT] = batch_size;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_WIDTH]  = hidden_size;
      }
    }
    else
    {
      if(outBufIdx == 0)
      {
        /* output shape: [batch_size, seq_length, num_directions, hidden_size] */
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_DIM2]   = batch_size;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_NUMCH]  = seq_length;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_HEIGHT] = num_directions;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_WIDTH]  = hidden_size;
      }
      else
      {
        /* output shape: [batch_size, 1, num_directions, hidden_size] */
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_DIM2]   = batch_size;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_NUMCH]  = 1;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_HEIGHT] = num_directions;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_WIDTH]  = hidden_size;
      }
    }
  }

  /**
   * Combine all the outputs to a single output with an increased buffer size
   * This is the final size of the GRU layer (i.e the runtime shape)
   */
  if(gruPCParams.isOutputSliced == 1)
  {
    for(int32_t outBufIdx = 0; outBufIdx < TIDLPCLayers.numOutBufs; outBufIdx++)
    {
      TIDL_shapeInfer_GRU(&TIDLPCLayers.layerParams, inDataParams, 1, &TIDLPCLayers.outData[outBufIdx], &ctx);
    }
  }

  return 0;
}

int32_t TIDL_tfOutReshapeRNNLayer(sTIDL_OrgNetwork_t *pOrgTIDLNetStructure, int32_t layerIndex)
{
  sTIDL_LayerPC_t &TIDLPCLayers = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex];
  sTIDL_RNNParams_t &rnnParams = TIDLPCLayers.layerParams.rnnParams;
  sTIDL_RNNPCParams_t &rnnPCParams = TIDLPCLayers.layerPCParams.rnnParams;
  sTIDL_DataParams_t *inDataParams[1] = { &TIDLPCLayers.inData[0] };
  TIDL_ShapeContext_t ctx;
  ctx.isCompileTime = 1;
  ctx.pcLayer       = (void *)&TIDLPCLayers;
  ctx.configParams  = (void *)&gParams;

  for(int32_t outBufIdx = 0; outBufIdx < TIDLPCLayers.numOutBufs; outBufIdx++)
  {
    TIDLPCLayers.outData[outBufIdx].elementType = TIDLPCLayers.inData[0].elementType;

    for(int32_t dimIdx = TIDL_DIM_BATCH; dimIdx < TIDL_DIM_MAX; dimIdx++)
    {
      TIDLPCLayers.outData[outBufIdx].dimValues[dimIdx] = TIDLPCLayers.inData[0].dimValues[dimIdx];
    }
  }

  int32_t seq_length, batch_size;
  if(rnnParams.layout == 0)
  {
    /* input shape: [seq_length, batch_size, input_size] */
    seq_length = TIDLPCLayers.inData[0].dimValues[TIDL_DIM_NUMCH];
    batch_size = TIDLPCLayers.inData[0].dimValues[TIDL_DIM_HEIGHT];
  }
  else
  {
    /* input shape: [batch_size, seq_length, input_size] */
    seq_length = TIDLPCLayers.inData[0].dimValues[TIDL_DIM_HEIGHT];
    batch_size = TIDLPCLayers.inData[0].dimValues[TIDL_DIM_NUMCH];
  }

  int32_t hidden_size = rnnParams.hidden_size;
  int32_t num_directions = 1;
  if(rnnParams.direction == TIDL_RecurrentBidirectional)
  {
    num_directions = 2;
  }

  for(int32_t outBufIdx = 0; outBufIdx < TIDLPCLayers.numOutBufs; outBufIdx++)
  {
    if(rnnParams.layout == 0)
    {
      if(outBufIdx == 0)
      {
        /* output shape: [seq_length, num_directions, batch_size, hidden_size] */
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_DIM2]   = seq_length;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_NUMCH]  = num_directions;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_HEIGHT] = batch_size;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_WIDTH]  = hidden_size;
      }
      else
      {
        /* output shape: [1, num_directions, batch_size, hidden_size] */
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_DIM2]   = 1;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_NUMCH]  = num_directions;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_HEIGHT] = batch_size;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_WIDTH]  = hidden_size;
      }
    }
    else
    {
      if(outBufIdx == 0)
      {
        /* output shape: [batch_size, seq_length, num_directions, hidden_size] */
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_DIM2]   = batch_size;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_NUMCH]  = seq_length;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_HEIGHT] = num_directions;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_WIDTH]  = hidden_size;
      }
      else
      {
        /* output shape: [batch_size, 1, num_directions, hidden_size] */
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_DIM2]   = batch_size;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_NUMCH]  = 1;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_HEIGHT] = num_directions;
        TIDLPCLayers.outData[outBufIdx].dimValues[TIDL_DIM_WIDTH]  = hidden_size;
      }
    }
  }

  /**
   * Combine all the outputs to a single output with an increased buffer size
   * This is the final size of the RNN layer (i.e the runtime shape)
   */
  if(rnnPCParams.isOutputSliced == 1)
  {
    for(int32_t outBufIdx = 0; outBufIdx < TIDLPCLayers.numOutBufs; outBufIdx++)
    {
      TIDL_shapeInfer_RNN(&TIDLPCLayers.layerParams, inDataParams, 1, &TIDLPCLayers.outData[outBufIdx], &ctx);
    }
  }

  return 0;
}

int32_t tidl_linkInputTensors(sTIDL_OrgNetwork_t  *pOrgTIDLNetStructure, int32_t layerIndex)
{
  int32_t i0, i1, i2;
  for (i0 = 0; i0 < pOrgTIDLNetStructure->TIDLPCLayers[layerIndex].numInBufs; i0++)
  {
    for (i1 = layerIndex - 1; i1 >= 0; i1--)
    {
      for (i2 = 0; i2 < pOrgTIDLNetStructure->TIDLPCLayers[i1].numOutBufs; i2++)
      {
        if (pOrgTIDLNetStructure->TIDLPCLayers[i1].outConsumerLinked[i2] < pOrgTIDLNetStructure->TIDLPCLayers[i1].outConsumerCnt[i2])
        {
          if (strcmp((const char *)pOrgTIDLNetStructure->TIDLPCLayers[layerIndex].inDataNames[i0], (const char *)pOrgTIDLNetStructure->TIDLPCLayers[i1].outDataNames[i2]) == 0)
          {
            pOrgTIDLNetStructure->TIDLPCLayers[layerIndex].inData[i0].dataId = pOrgTIDLNetStructure->TIDLPCLayers[i1].outData[i2].dataId;
            pOrgTIDLNetStructure->TIDLPCLayers[i1].outConsumerLinked[i2]++;
          }
        }
      }
    }
  }
  return 0;
}


int32_t tidl_linkOutputTensors(sTIDL_OrgNetwork_t  *pOrgTIDLNetStructure, int32_t layerIndex)
{
  int32_t i0, i1, i2;
  for (i0 = 0; i0 < pOrgTIDLNetStructure->TIDLPCLayers[layerIndex].numOutBufs; i0++)
  {
    for (i1 = layerIndex - 1; i1 >= 0; i1--)
    {
      for (i2 = 0; i2 < pOrgTIDLNetStructure->TIDLPCLayers[i1].numInBufs; i2++)
      {
        if (pOrgTIDLNetStructure->TIDLPCLayers[layerIndex].outConsumerLinked[i0] < pOrgTIDLNetStructure->TIDLPCLayers[layerIndex].outConsumerCnt[i0])
        {
          if (strcmp((const char *)pOrgTIDLNetStructure->TIDLPCLayers[layerIndex].outDataNames[i0], (const char *)pOrgTIDLNetStructure->TIDLPCLayers[i1].inDataNames[i2]) == 0)
          {
            pOrgTIDLNetStructure->TIDLPCLayers[i1].inData[i2].dataId = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex].outData[i0].dataId;
            pOrgTIDLNetStructure->TIDLPCLayers[layerIndex].outConsumerLinked[i0]++;
            if(pOrgTIDLNetStructure->TIDLPCLayers[layerIndex].layerType == TIDL_OdOutputReformatLayer)
            {
              pOrgTIDLNetStructure->TIDLPCLayers[i1].inData[i2] = pOrgTIDLNetStructure->TIDLPCLayers[layerIndex].outData[0];
            }
          }
        }
      }
    }
  }
  return 0;
}


int32_t tidl_getConsumerCount(sTIDL_OrgNetwork_t  *pOrgTIDLNetStructure, int32_t layerIndex, const char * name)
{
  int32_t i0, i1, i2;
  int32_t outConsumerLinked = 0;
  for (i1 = layerIndex - 1; i1 >= 0; i1--)
  {
    for (i2 = 0; i2 < pOrgTIDLNetStructure->TIDLPCLayers[i1].numInBufs; i2++)
    {
      if (strcmp((const char *)pOrgTIDLNetStructure->TIDLPCLayers[i1].inDataNames[i2], (const char *)name) == 0)
      {
        outConsumerLinked++;
      }
    }
  }
  return outConsumerLinked;
}

int32_t tidl_isAllInsAvailable(sTIDL_LayerPC_t  *orgLayer, sTIDL_OrgNetwork_t  *ptempTIDLNetStructure, int32_t layerIndex)
{
  int32_t i0, i1, i2;
  int32_t status = 0;
  int32_t availableIns = 0;
  for (i0 = 0; i0 < orgLayer->numInBufs; i0++)
  {
    for (i1 = 0; i1 < layerIndex; i1++)
    {
      for (i2 = 0; i2 < ptempTIDLNetStructure->TIDLPCLayers[i1].numOutBufs; i2++)
      {
        if (strcmp((const char *)ptempTIDLNetStructure->TIDLPCLayers[i1].outDataNames[i2], (const char *)orgLayer->inDataNames[i0]) == 0)
        {
          // TIDL_GLOBAL_REPORT_INFO(TIDL_IMPORT_DIAGNOSIS_DEBUG_LEVEL, "Ins %s vs %s ", (const char *)ptempTIDLNetStructure->TIDLPCLayers[i1].outDataNames[i2], (const char *)orgLayer->inDataNames[i0]);
          availableIns++;
        }
      }
    }
  }
  /* Is shall be orgLayer->numInBufs <= availableIns, temprary fix to get caffe import working
     TODO : need rever back after migatration caffe to new import framework */

  if ((orgLayer->numInBufs <= availableIns) || (orgLayer->numInBufs == -1))
  {
    status = 1;
  }
  return(status);
}

std::vector<int32_t> tidl_getInLayersByName (sTIDL_OrgNetwork_t& orgTIDLNetStructure, sTIDL_LayerPC_t& layer)
{
  int32_t i1 = 0, i2 = 0, i3 = 0;
  vector<int32_t> inLayers;

  for (i1 = 0; i1 < layer.numInBufs; i1++)
  {
    for (i2 = 0; i2 < orgTIDLNetStructure.numLayers; i2++)
    {
      for (i3 = 0; i3 < orgTIDLNetStructure.TIDLPCLayers[i2].numOutBufs; i3++)
      {
        if (strcmp ((char*)layer.inDataNames[i1], (char*)orgTIDLNetStructure.TIDLPCLayers[i2].outDataNames[i3]) == 0)
        {
          inLayers.push_back(i2);
        }
      }
    }
  }

  return inLayers;
}
std::vector<int32_t> tidl_getOutLayersByName (sTIDL_OrgNetwork_t& orgTIDLNetStructure, sTIDL_LayerPC_t& layer)
{
  int32_t i1 = 0, i2 = 0, i3 = 0;
  vector<int32_t> outLayers;

  for (i1 = 0; i1 < layer.numOutBufs; i1++)
  {
    for (i2 = 0; i2 < orgTIDLNetStructure.numLayers; i2++)
    {
      for (i3 = 0; i3 < orgTIDLNetStructure.TIDLPCLayers[i2].numInBufs; i3++)
      {
        if (strcmp ((char*)layer.outDataNames[i1], (char*)orgTIDLNetStructure.TIDLPCLayers[i2].inDataNames[i3]) == 0)
        {
          outLayers.push_back(i2);
        }
      }
    }
  }

  return outLayers;
}

int32_t tidl_sortDataIDsinPCNet (sTIDL_OrgNetwork_t *pOrgTIDLNetStructure, int32_t dataIdLayerIdConstraint)
{
  int32_t status = 0, i1 = 0, i2 = 0, i3 = 0, dataId = 0;
  int32_t numLayers = pOrgTIDLNetStructure->numLayers;

  for (i1 = 0; i1 < numLayers; i1++)
  {
    if (dataIdLayerIdConstraint == MAKE_LAYERID_DATAID_SAME)
    {
      if (pOrgTIDLNetStructure->TIDLPCLayers[i1].layerType == TIDL_DataLayer &&
          pOrgTIDLNetStructure->TIDLPCLayers[i1].numOutBufs == -1)
      {
        /**
         * Output data layer doesn't have any output buffers
         * We still increment dataId to keep layerIds and dataIds in sync
        */
        dataId++;
      }      
    }

    for (i2 = 0; i2 < pOrgTIDLNetStructure->TIDLPCLayers[i1].numOutBufs; i2++)
    {
      pOrgTIDLNetStructure->TIDLPCLayers[i1].outData[i2].dataId = dataId++;
    }
  }

  /* Link the new data IDs */

  for (i1 = 0; i1 < numLayers; i1++)
  {
    sTIDL_LayerPC_t& layer = pOrgTIDLNetStructure->TIDLPCLayers[i1];
    vector<int32_t> inLayers = tidl_getInLayersByName(*pOrgTIDLNetStructure, layer);

    for (int32_t layerIdx: inLayers)
    {
      for (i2 = 0; i2 < layer.numInBufs; i2++)
      {
        for(i3 = 0; i3 < pOrgTIDLNetStructure->TIDLPCLayers[layerIdx].numOutBufs; i3++)
        {
          if (strcmp((char*)layer.inDataNames[i2], (char*)pOrgTIDLNetStructure->TIDLPCLayers[layerIdx].outDataNames[i3]) == 0)
          {
            layer.inData[i2].dataId = pOrgTIDLNetStructure->TIDLPCLayers[layerIdx].outData[i3].dataId;
          }
        }
      }
    }
  }
  return dataId;
}

int32_t tidl_sortLayersInProcOrder(sTIDL_OrgNetwork_t  *pOrgTIDLNetStructure, sTIDL_OrgNetwork_t  *ptempTIDLNetStructure, int32_t layerIndex)
{
  memset((void *)ptempTIDLNetStructure, 0, sizeof(pOrgTIDLNetStructure));
  int32_t status = 0;
  /* Set indegrees of all the layers where indegree of any layer refer to number of producers of that layer */
  int32_t numLayers = pOrgTIDLNetStructure->numLayers;
  int32_t inDegree[numLayers] = {0};
  int32_t i = 0;
  for (i = 0; i < numLayers; i++)
  {
    inDegree[i] = pOrgTIDLNetStructure->TIDLPCLayers[i].numInBufs;
    inDegree[i] = (inDegree[i] == -1) ? 0 : inDegree[i];
  }
  /* Start with all the layers having indegree 0 - input data layers*/
  queue<int> q;
  for (i = 0; i < numLayers; i++)
  {
    if(inDegree[i] == 0)
    {
      q.push(i);
    }
  }
  int32_t newNetIdx = 0;
  while(!q.empty())
  {
    int32_t layerIdx = q.front();
    q.pop();
    ptempTIDLNetStructure->TIDLPCLayers[newNetIdx++] = pOrgTIDLNetStructure->TIDLPCLayers[layerIdx];
    vector<int32_t> outLayers = tidl_getOutLayersByName(*pOrgTIDLNetStructure, pOrgTIDLNetStructure->TIDLPCLayers[layerIdx]);

    for (int32_t outIdx: outLayers)
    {
      inDegree[outIdx]--;
      if (inDegree[outIdx] == 0)
      {
        q.push(outIdx);
      }
    }
  }

  if (newNetIdx != numLayers)
  {
    TIDL_GLOBAL_REPORT_INFO(TIDL_IMPORT_DIAGNOSIS_DEBUG_LEVEL, "Error in topologically sorting the network");
    status = -1;
    #if TIDL_IMPORT_SORT_LAYERS_DEBUG
    int32_t i = 0, j = 0, layerFound = false;
    for (i = 0; i < numLayers; i++)
    {
      layerFound = false;
      for (j = 0; j < newNetIdx; j++)
      {
        if (strcmp ((char*)pOrgTIDLNetStructure->TIDLPCLayers[i].outDataNames[0] ,(char*)ptempTIDLNetStructure->TIDLPCLayers[j].outDataNames[0]) == 0)
        {
          layerFound = true;
        }
      }
      if (layerFound == false)
      {
        TIDL_GLOBAL_REPORT_INFO(TIDL_IMPORT_DIAGNOSIS_DEBUG_LEVEL, "Original layerIdx %d, name %s, layerType %d not found in new sorted network\n", i ,
        pOrgTIDLNetStructure->TIDLPCLayers[i].outDataNames[0],
        pOrgTIDLNetStructure->TIDLPCLayers[i].layerType);
      }
    }
    #endif
  }
  else 
  {
    /* Update the netStructure & sort the DataIDs*/
    ptempTIDLNetStructure->numLayers = numLayers;
    ptempTIDLNetStructure->NCExecMode = pOrgTIDLNetStructure->NCExecMode;
    *pOrgTIDLNetStructure = *ptempTIDLNetStructure;
    tidl_sortDataIDsinPCNet(pOrgTIDLNetStructure);
  }
  return status;
}

void tidl_replaceInTensorName(sTIDL_OrgNetwork_t  *pOrgTIDLNetStructure, int32_t layerIndex, char * orgTensorName, char * newTensorName)
{
  int32_t i0, i1, i2;
  int32_t newNetIdx = 0;

  for (i0 = 0; i0 < layerIndex; i0++)
  {
    for (i1 = 0; i1 < pOrgTIDLNetStructure->TIDLPCLayers[i0].numInBufs; i1++)
    {
      if(strcmp((const char *)pOrgTIDLNetStructure->TIDLPCLayers[i0].inDataNames[i1],(const char *)orgTensorName) == 0)
      {
        strcpy((char *)pOrgTIDLNetStructure->TIDLPCLayers[i0].inDataNames[i1], (const char *)newTensorName);
      }
    }
  }
}

int32_t tidl_removeMergedLayersFromNet(sTIDL_OrgNetwork_t  *pOrgTIDLNetStructure, sTIDL_OrgNetwork_t  *ptempTIDLNetStructure)
{
  int32_t i0, i1, i2;
  int32_t newNetIdx = 0;

  int32_t layerIndex = pOrgTIDLNetStructure->numLayers;
  memset((void *)ptempTIDLNetStructure, 0, sizeof(orgTIDLNetStructure));
  for (i0 = 0; i0 < layerIndex; i0++)
  {
    if ((pOrgTIDLNetStructure->TIDLPCLayers[i0].numInBufs != -1) ||
      (pOrgTIDLNetStructure->TIDLPCLayers[i0].numOutBufs != -1))
    {
      ptempTIDLNetStructure->TIDLPCLayers[newNetIdx] = pOrgTIDLNetStructure->TIDLPCLayers[i0];
      newNetIdx++;
    }
  }
  ptempTIDLNetStructure->numLayers = newNetIdx;
  *pOrgTIDLNetStructure = *ptempTIDLNetStructure;

  tidl_sortDataIDsinPCNet(pOrgTIDLNetStructure);
  return 0;
}
int32_t tidl_upateAInDataId(sTIDL_OrgNetwork_t  *pOrgTIDLNetStructure, int32_t layerIndex, int32_t oldId, int32_t currId)
{
  int32_t i0, i1, i2, i3, i4;
  for (i3 = 0; i3 < layerIndex; i3++)
  {
    for (i4 = 0; i4 < pOrgTIDLNetStructure->TIDLPCLayers[i3].numInBufs; i4++)
    {
      if (pOrgTIDLNetStructure->TIDLPCLayers[i3].inData[i4].dataId == oldId)
      {
        pOrgTIDLNetStructure->TIDLPCLayers[i3].inData[i4].dataId = currId;
      }
    }
  }
  return 0;
}

int32_t tidl_sortDataIds(sTIDL_OrgNetwork_t *pOrgTIDLNetStructure)
{
  int32_t i0, i1, i2, i3, i4;
  int32_t maxDataId = 0;
  int32_t currId = 0;
  int32_t oldId = 0;
  int32_t layerIndex = pOrgTIDLNetStructure->numLayers;
  for (i1 = 0; i1 < layerIndex; i1++)
  {
    for (i2 = 0; i2 < pOrgTIDLNetStructure->TIDLPCLayers[i1].numOutBufs; i2++)
    {
      maxDataId = pOrgTIDLNetStructure->TIDLPCLayers[i1].outData[i2].dataId >= maxDataId ? pOrgTIDLNetStructure->TIDLPCLayers[i1].outData[i2].dataId : maxDataId;
    }
  }
  maxDataId = maxDataId + 1;
  for (i1 = 0; i1 < layerIndex; i1++)
  {
    for (i2 = 0; i2 < pOrgTIDLNetStructure->TIDLPCLayers[i1].numOutBufs; i2++)
    {
      pOrgTIDLNetStructure->TIDLPCLayers[i1].outData[i2].dataId += maxDataId;
    }
    for (i2 = 0; i2 < pOrgTIDLNetStructure->TIDLPCLayers[i1].numInBufs; i2++)
    {
      pOrgTIDLNetStructure->TIDLPCLayers[i1].inData[i2].dataId += maxDataId;
    }
  }

  for (i1 = 0; i1 < layerIndex; i1++)
  {
    for (i2 = 0; i2 < pOrgTIDLNetStructure->TIDLPCLayers[i1].numOutBufs; i2++)
    {
      oldId = pOrgTIDLNetStructure->TIDLPCLayers[i1].outData[i2].dataId;
      //currId = i1;
      pOrgTIDLNetStructure->TIDLPCLayers[i1].outData[i2].dataId = currId;
      tidl_upateAInDataId(pOrgTIDLNetStructure, layerIndex, oldId, currId);
      currId++;
    }
  }
  return 0;
}

int32_t tidl_makeDataIdLayerIdSame(sTIDL_OrgNetwork_t  *pOrgTIDLNetStructure, int32_t layerIndex)
{
  int32_t i0, i1, i2, i3, i4;
  int32_t maxDataId = 0;
  int32_t currId = 0;
  int32_t oldId = 0;
  for (i1 = 0; i1 < layerIndex; i1++)
  {
    for (i2 = 0; i2 < pOrgTIDLNetStructure->TIDLPCLayers[i1].numOutBufs; i2++)
    {
      maxDataId = pOrgTIDLNetStructure->TIDLPCLayers[i1].outData[i2].dataId >= maxDataId ? pOrgTIDLNetStructure->TIDLPCLayers[i1].outData[i2].dataId : maxDataId;
    }
  }
  maxDataId = maxDataId + 1;
  for (i1 = 0; i1 < layerIndex; i1++)
  {
    for (i2 = 0; i2 < pOrgTIDLNetStructure->TIDLPCLayers[i1].numOutBufs; i2++)
    {
      pOrgTIDLNetStructure->TIDLPCLayers[i1].outData[i2].dataId += maxDataId;
    }
    for (i2 = 0; i2 < pOrgTIDLNetStructure->TIDLPCLayers[i1].numInBufs; i2++)
    {
      pOrgTIDLNetStructure->TIDLPCLayers[i1].inData[i2].dataId += maxDataId;
    }
  }
  for (i1 = 0; i1 < layerIndex; i1++)
  {
    for (i2 = 0; i2 < pOrgTIDLNetStructure->TIDLPCLayers[i1].numOutBufs; i2++)
    {
      oldId = pOrgTIDLNetStructure->TIDLPCLayers[i1].outData[i2].dataId;
      currId = i1;
      pOrgTIDLNetStructure->TIDLPCLayers[i1].outData[i2].dataId = currId;
      tidl_upateAInDataId(pOrgTIDLNetStructure, layerIndex, oldId, currId);
    }
  }
  return 0;
}

int32_t tidl_updateOutDataShape(sTIDL_OrgNetwork_t  &pOrgTIDLNetStructure, int32_t startIdx, int32_t layerIndex, sTIDL_tfOutReshapeMap_t * sTIDL_tfOutReshapeTable)
{
  int32_t i1, i2, i3, i4;
  int32_t status = 0;

  for (i1 = startIdx; i1 < layerIndex; i1++)
  {
    if(pOrgTIDLNetStructure.TIDLPCLayers[i1].layerType != TIDL_DataLayer)
    {
      pOrgTIDLNetStructure.TIDLPCLayers[i1].outData[0].numBatchH = pOrgTIDLNetStructure.TIDLPCLayers[i1].inData[0].numBatchH;
      pOrgTIDLNetStructure.TIDLPCLayers[i1].outData[0].numBatchW = pOrgTIDLNetStructure.TIDLPCLayers[i1].inData[0].numBatchW;
    }
    status = sTIDL_tfOutReshapeTable[pOrgTIDLNetStructure.TIDLPCLayers[i1].layerType].tidl_tfOutReshape(&pOrgTIDLNetStructure, i1);

    // Update dynDimMask 
    /*  0x3F means all 6 input dimensions are variable.  If any of the input is dynamic(i.e dynDimMask != 0 ),
        we assume all outputs should also have all dimensions variable.
        TODO: Update only the necessary dimensions instead of setting all to variable. */
    for ( int inIdx = 0 ; inIdx < pOrgTIDLNetStructure.TIDLPCLayers[i1].numInBufs ; inIdx++)
    {
      if( pOrgTIDLNetStructure.TIDLPCLayers[i1].inData[inIdx].dynDimMask != 0 )
      {
        for ( int outIdx = 0 ; outIdx < pOrgTIDLNetStructure.TIDLPCLayers[i1].numOutBufs ; outIdx++)
        {
          pOrgTIDLNetStructure.TIDLPCLayers[i1].outData[outIdx].dynDimMask = 0x3F;
        }
        break;
      }
    }

    /* The below code within the "if (status != -1)"" condition has potential bugs due to which some parametrs in the first layer parameters of the cut out n/w are not coming out correct. To be fixed*/
    if (status != -1)
    {
      for (i2 = 0; i2 < pOrgTIDLNetStructure.TIDLPCLayers[i1].numOutBufs; i2++)
      {
        for (i3 = 0; i3 < pOrgTIDLNetStructure.numLayers; i3++)
        {
          for (i4 = 0; i4 < pOrgTIDLNetStructure.TIDLPCLayers[i3].numInBufs; i4++)
          {
            if (pOrgTIDLNetStructure.TIDLPCLayers[i3].inData[i4].dataId == pOrgTIDLNetStructure.TIDLPCLayers[i1].outData[i2].dataId)
            {
              pOrgTIDLNetStructure.TIDLPCLayers[i3].inData[i4] = pOrgTIDLNetStructure.TIDLPCLayers[i1].outData[i2];
            }
          }
        }
      }
    }
    else
    {
      /* this case needs review, printing warning for now */
      TIDL_GLOBAL_REPORT_WARNING("Reshape for layerType = %d failed", pOrgTIDLNetStructure.TIDLPCLayers[i1].layerType);
    }
  }
  return status;
}
